mapper.select:
SELECT long_wait_warning_minutes
FROM stores
WHERE id = #{storeId}

mapper.update:
UPDATE stores
SET long_wait_warning_minutes = #{longWaitWarningMinutes}
WHERE id = #{storeId}

UPDATE stores
SET branch_name = #{branchName}, address = #{address}, phone = #{phone}, email = #{email},
    google_maps_location = #{googleMapsLocation}, open_time = #{openTime},
    close_time = #{closeTime}, status = #{status}
WHERE id = #{storeId}
